/// The extended error codes this specification declares (SPEC §7.3 item 9,
/// §8.5), in declaration order. Empty when it declares none.
pub const ERROR_CODES: &[crate::DeclaredErrorCode] = &[
    error_codes::NOT_FOUND,
    error_codes::INCOMPLETE,
    error_codes::DIGEST_MISMATCH,
];
/// One constant per extended error code this specification declares
/// (SPEC §7.3 item 9), named for its local part.
///
/// Emit these rather than a string literal: the code is read from the
/// specification, so it cannot name a code the specification never
/// declared.
pub mod error_codes {
    /// `rooms/blobs/upload/commit:notFound`
    ///
    /// No upload with this id exists that the caller may commit. Conflates an unknown id, an expired or aborted upload, and another party's upload.
    ///
    /// Declared `retryable: false`.
    pub const NOT_FOUND: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "rooms/blobs/upload/commit:notFound",
        retryable: false,
        details_schema: ::core::option::Option::None,
    };
    /// `rooms/blobs/upload/commit:incomplete`
    ///
    /// Chunks are missing. `details.remainingCount` says how many; `rooms/blobs/upload/begin` with the same manifest says which.
    ///
    /// Declared `retryable: true`.
    /// Declares a `detailsSchema` for the error's `details` member.
    pub const INCOMPLETE: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "rooms/blobs/upload/commit:incomplete",
        retryable: true,
        details_schema: ::core::option::Option::Some(
            "{\"additionalProperties\":false,\"maxProperties\":1,\"properties\":{\"remainingCount\":{\"minimum\":1,\"type\":\"integer\"}},\"required\":[\"remainingCount\"],\"type\":\"object\"}",
        ),
    };
    /// `rooms/blobs/upload/commit:digestMismatch`
    ///
    /// Every chunk verified, but the reassembled ciphertext does not hash to the manifest's `digest` — the chunks are right and the order or the commitment is wrong. Nothing is stored; the upload is discarded and its reservation released.
    ///
    /// Declared `retryable: false`.
    pub const DIGEST_MISMATCH: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "rooms/blobs/upload/commit:digestMismatch",
        retryable: false,
        details_schema: ::core::option::Option::None,
    };
}
